                    "parameters": {
                        "type": "object",
                        "properties": {
                            "usuario_id": {"type": "string"},
                            "productos": {"type": "array"},
                            "direccion_envio": {"type": "string"}
                        }
                    }
                }
            },
            {
                "type": "function",
                "function": {
                    "name": "obtener_recomendaciones",
                    "description": "Obtiene productos recomendados",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "usuario_id": {"type": "string"},
                            "cantidad": {"type": "integer"}
                        }
                    }
                }
            }
        ]

    def procesar_solicitud(self, usuario_id, solicitud_natural):
        """Procesa solicitudes en lenguaje natural"""

